// ===== EDIT THIS =====
const CHANNEL = 'REPLACE_WITH_SLACK_CHANNEL_ID';
// Slack buttons need an HTTPS n8n URL. Keep false until n8n is served over HTTPS.
const SHOW_BUTTONS = false;
// =====================
const TITLES = {
  applied: (d) => (d.mode === 'auto' ? '✅ Applied automatically' : '✅ Applied (you approved)'),
  needs_approval: () => '🟡 Needs your approval',
  dry_run: () => '🧪 Dry run: would have applied automatically',
  cap_reached: () => '⛔ Daily cap reached: not applied',
  apply_failed: () => '❌ Apply failed',
  queued: () => '⏳ Queued: being submitted shortly',
  skipped: () => '⏭️ Skipped',
};
const ACTIONABLE = ['needs_approval', 'dry_run', 'cap_reached', 'apply_failed'];
const clip = (s, n) => { s = s || ''; return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const esc = (s) => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Escape first, then split so no piece exceeds Slack's 3,000-char text limit,
// and never cut in the middle of an &amp; / &lt; / &gt; entity.
const pieces = (raw, n, max) => {
  const s = esc(raw || ''); const out = []; let i = 0;
  while (i < s.length && out.length < max) {
    let end = Math.min(i + n, s.length);
    const amp = s.lastIndexOf('&', end - 1);
    if (end < s.length && amp > end - 5 && s.indexOf(';', amp) >= end) end = amp;
    out.push(s.slice(i, end)); i = end;
  }
  return out;
};

function buildMessage(d, note) {
  const title = (TITLES[d.event] || (() => d.event))(d);
  const c = d.client || {};
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: clip(title, 150), emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: `*<${d.url}|${esc(clip(d.title, 140))}>*` } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Budget:* ${d.budget}` },
      { type: 'mrkdwn', text: `*Our bid:* $${d.bid}` },
      { type: 'mrkdwn', text: `*Fit score:* ${d.fit_score == null ? '-' : d.fit_score}` },
      { type: 'mrkdwn', text: `*Applied (24h):* ${d.applied_in_last_24h}/${d.daily_cap}` },
      { type: 'mrkdwn', text: `*Client:* ${c.country || '-'} · spent ${c.total_spent || '$0'} · ${c.reviews || 0} reviews` },
      { type: 'mrkdwn', text: `*Mode:* ${d.mode === 'auto' ? 'auto-apply (under $3,000)' : 'needs approval ($3,000+)'}` },
    ] },
  ];
  if (d.error) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `:warning: ${esc(clip(d.error, 800))}` } });
  if (note) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: esc(clip(note, 500)) }] });
  if (d.screening_questions && d.screening_questions.length) {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: *The post asks screening questions* (answer them on Upwork if applying fails):\n' + d.screening_questions.slice(0, 6).map((q) => '• ' + esc(clip(q, 250))).join('\n') } });
  }
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Job description*' } });
  pieces(d.description, 2800, 2).forEach((p) => blocks.push({ type: 'section', text: { type: 'mrkdwn', text: p } }));
  if ((d.description || '').length > 5600) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Description truncated. Full text at the job link.' }] });
  blocks.push({ type: 'divider' });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Cover letter*' } });
  pieces(d.cover_letter, 2800, 2).forEach((p) => blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '```' + p + '```' } }));
  if (ACTIONABLE.includes(d.event) && !SHOW_BUTTONS) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Buttons are switched off. To apply, open the job: <${d.url}|Open on Upwork>` }] });
  }
  if (ACTIONABLE.includes(d.event) && SHOW_BUTTONS) {
    blocks.push({ type: 'actions', block_id: 'job_actions', elements: [
      { type: 'button', action_id: 'apply', value: d.job_id, style: 'primary',
        text: { type: 'plain_text', text: d.event === 'apply_failed' ? 'Retry apply' : 'Apply now' },
        confirm: { title: { type: 'plain_text', text: 'Submit this proposal?' }, text: { type: 'mrkdwn', text: 'This sends the proposal to the client and spends Connects.' }, confirm: { type: 'plain_text', text: 'Apply' }, deny: { type: 'plain_text', text: 'Cancel' } } },
      { type: 'button', action_id: 'edit', value: d.job_id, text: { type: 'plain_text', text: 'Edit letter' } },
      { type: 'button', action_id: 'skip', value: d.job_id, text: { type: 'plain_text', text: 'Skip' } },
    ] });
  }
  return { channel: CHANNEL, text: `${title}: ${d.title}`, blocks };
}

const body = $input.first().json.body || $input.first().json;
return [{ json: buildMessage(body, '') }];

// Only YOU can click the buttons. Put your Slack member ID here (profile > ... > Copy member ID).
const ALLOWED_USER = 'REPLACE_WITH_YOUR_SLACK_USER_ID';
const first = $input.first().json;
const raw = (first.body && first.body.payload) || first.payload;
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!p || !p.user || p.user.id !== ALLOWED_USER) return [{ json: { route: 'ignore' } }];
if (p.type === 'block_actions') {
  const a = p.actions[0];
  return [{ json: { route: a.action_id, job_id: a.value, channel: p.container.channel_id, ts: p.container.message_ts, trigger_id: p.trigger_id } }];
}
if (p.type === 'view_submission' && p.view.callback_id === 'edit_letter') {
  const meta = JSON.parse(p.view.private_metadata);
  const letter = p.view.state.values.letter_block.letter_input.value;
  return [{ json: { route: 'save_letter', job_id: meta.job_id, channel: meta.channel, ts: meta.ts, letter } }];
}
return [{ json: { route: 'ignore' } }];

const esc = (s) => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => { s = s || ''; return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const d = $input.first().json;
const p = $('Parse Slack payload').first().json;
const letter = d.cover_letter || '';
const canEdit = letter.length <= 3000;   // Slack text inputs hold at most 3,000 characters
const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: '*' + esc(clip(d.title, 120)) + '*' } }];
const view = {
  type: 'modal', callback_id: 'edit_letter',
  private_metadata: JSON.stringify({ job_id: p.job_id, channel: p.channel, ts: p.ts }),
  title: { type: 'plain_text', text: 'Edit cover letter' },
  close: { type: 'plain_text', text: 'Close' },
  blocks,
};
if (canEdit) {
  view.submit = { type: 'plain_text', text: 'Save' };
  blocks.push({ type: 'input', block_id: 'letter_block', label: { type: 'plain_text', text: 'Cover letter' },
    element: { type: 'plain_text_input', action_id: 'letter_input', multiline: true, initial_value: letter, max_length: 3000 } });
} else {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: 'This letter is longer than Slack allows in an edit box (3,000 characters). Edit it on Upwork instead.' } });
}
return [{ json: { trigger_id: p.trigger_id, view } }];

